/** Size class of a Turn by its estimated tokens; see `notes/buckets.md`. */
export type Bucket = "tiny" | "small" | "medium" | "large" | "huge";

/**
 * The bucket a Turn of `tokens` estimated tokens falls in. Lower bounds are
 * inclusive, upper bounds exclusive, so every size lands in exactly one.
 */
export function bucketOf(tokens: number): Bucket {
	if (tokens < 350) return "tiny";
	if (tokens < 1800) return "small";
	if (tokens < 7000) return "medium";
	if (tokens < 24000) return "large";
	return "huge";
}

