export const BUCKETS = ["tiny", "small", "medium", "large", "huge"] as const;

export type Bucket = (typeof BUCKETS)[number];

/**
 * The bucket a Turn of `tokens` estimated tokens falls in. Lower bounds are
 * inclusive, upper bounds exclusive, so every size lands in exactly one.
 *
 * @throws RangeError when `tokens` is negative or not finite (NaN, ±Infinity).
