import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";
import { reconstructTurns } from "./turns.ts";

/** Size classes of a Turn by its estimated tokens, smallest to largest; see `notes/buckets.md`. */
export const BUCKETS = ["tiny", "small", "medium", "large", "huge"] as const;

export type Bucket = (typeof BUCKETS)[number];

/**
 * The bucket a Turn of `tokens` estimated tokens falls in (lower bounds inclusive).
 * @throws RangeError if `tokens` is negative or not finite.
 */
export function bucketOf(tokens: number): Bucket {
	if (!Number.isFinite(tokens) || tokens < 0) {
		throw new RangeError(`Turn size must be a finite, non-negative token count; got ${tokens}`);
	}
	if (tokens < 350) return "tiny";
	if (tokens < 1800) return "small";
	if (tokens < 7000) return "medium";
	if (tokens < 24000) return "large";
	return "huge";
}

/**
 * The `approximateTokens` estimate of each Turn in `messages`, in order.
 *
 * Messages before the first user prompt have no prompt to belong to, so
 * `reconstructTurns` gathers them into a leading Turn whose `prompt` is `""`;
 * that Turn is dropped. It is recognised by its first message not being a
 * user message rather than by its empty prompt, so a real Turn whose user
 * message happens to have no text is kept.
 */
export function turnSizes(messages: HarnessMessage[]): number[] {
	return reconstructTurns(messages)
		.filter((turn) => turn.messages[0]?.role === "user")
		.map((turn) => approximateTokens(turn.messages));
}

/**
 * How many of `sizes` fall in each bucket, largest bucket first. Every bucket
 * gets an entry, with count 0 when empty, except `huge`, which is left out
 * when no size falls in it; see `notes/samples.md`.
 * @throws RangeError if any size is negative or not finite.
 */
export function histogram(sizes: number[]): { bucket: Bucket; count: number }[] {
	const counts: Record<Bucket, number> = { tiny: 0, small: 0, medium: 0, large: 0, huge: 0 };
	for (const size of sizes) counts[bucketOf(size)] += 1;
	return BUCKETS.toReversed()
		.map((bucket) => ({ bucket, count: counts[bucket] }))
		.filter(({ bucket, count }) => bucket !== "huge" || count > 0);
}

