import { describe, expect, test } from "bun:test";

import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";
import { bucketOf, histogram, turnSizes, type Bucket } from "./budget-table.ts";

describe("bucketOf", () => {
	const boundaries: [number, Bucket][] = [
		[0, "tiny"],
		[349, "tiny"],
		[350, "small"],
		[1799, "small"],
		[1800, "medium"],
		[6999, "medium"],
		[7000, "large"],
		[23999, "large"],
		[24000, "huge"],
	];

	test.each(boundaries)("%p tokens is %p", (tokens, bucket) => {
		expect(bucketOf(tokens)).toBe(bucket);
	});

	test.each([-1, -0.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY])(
		"%p tokens throws RangeError",
		(tokens) => {
			expect(() => bucketOf(tokens)).toThrow(RangeError);
		},
	);
});

describe("turnSizes", () => {
	const preamble: HarnessMessage = { role: "assistant", content: "p".repeat(800) };
	const firstPrompt: HarnessMessage = { role: "user", content: "summarise the log" };
	const firstReply: HarnessMessage = { role: "assistant", content: "a".repeat(120) };
	const secondPrompt: HarnessMessage = { role: "user", content: "now the errors only" };
	const secondReply: HarnessMessage = { role: "assistant", content: "b".repeat(2000) };
	const conversation = [preamble, firstPrompt, firstReply, secondPrompt, secondReply];

	test("sizes each prompted Turn over its own messages and drops the leading Turn", () => {
		expect(turnSizes(conversation)).toEqual([
			approximateTokens([firstPrompt, firstReply]),
			approximateTokens([secondPrompt, secondReply]),
		]);
	});

	test("the leading messages do not count towards the first Turn", () => {
		expect(turnSizes(conversation)).toEqual(turnSizes(conversation.slice(1)));
	});

	test("only messages before any prompt give no sizes", () => {
		expect(turnSizes([preamble])).toEqual([]);
	});

	test("a Turn whose prompt has no text is kept", () => {
		const blankPrompt: HarnessMessage = { role: "user", content: "" };
		expect(turnSizes([preamble, blankPrompt, firstReply])).toEqual([
			approximateTokens([blankPrompt, firstReply]),
		]);
	});
});

describe("histogram", () => {
	test("counts the sample sizes per bucket, largest bucket first", () => {
		expect(histogram([120, 90, 2400, 400, 8000])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 1 },
			{ bucket: "small", count: 1 },
			{ bucket: "tiny", count: 2 },
		]);
	});

	test("keeps empty buckets below huge at zero and leaves out an empty huge", () => {
		expect(histogram([500, 1000, 20000])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 2 },
			{ bucket: "tiny", count: 0 },
		]);
	});

	test("an empty list gives every bucket but huge at zero", () => {
		expect(histogram([])).toEqual([
			{ bucket: "large", count: 0 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 0 },
		]);
	});
});

