		.filter(({ bucket, count }) => bucket !== "huge" || count > 0);
}

/** The plain, unweighted sum of `sizes`; 0 for none. */
export function totalOf(sizes: number[]): number {
	return sizes.reduce((total, size) => total + size, 0);
}

/** What a Turn's size is multiplied by for its bucket; see `notes/weights.md`. */
const WEIGHTS: Record<Bucket, number> = { tiny: 0.5, small: 1, medium: 1.25, large: 1.5, huge: 2.25 };

/**
 * Each of `sizes` times the weight of its bucket, in the same order. Unrounded.
 * @throws RangeError if any size is negative or not finite.
 */
export function weighted(sizes: number[]): number[] {
