// suite: TT-5082
import { describe, expect, test } from "bun:test";

import { weighted } from "./budget-table.ts";

describe("weighted", () => {
	test("multiplies each size by its bucket's weight, keeping the order", () => {
		expect(weighted([30000, 100, 10000, 1000, 2000])).toEqual([67500, 50, 15000, 1000, 2500]);
	});

	test("the weight changes at each bucket boundary", () => {
		expect(weighted([349, 350, 1799, 1800, 6999, 7000, 23999, 24000])).toEqual([
			174.5, 350, 1799, 2250, 8748.75, 10500, 35998.5, 54000,
		]);
	});

	test("leaves fractional results unrounded", () => {
		expect(weighted([1, 1801])).toEqual([0.5, 2251.25]);
	});

	test("an empty list gives no weighted sizes", () => {
		expect(weighted([])).toEqual([]);
	});

	test("a negative size throws RangeError", () => {
		expect(() => weighted([500, -1])).toThrow(RangeError);
	});
});

