	tiny: "crumbs",
	small: "bites",
	medium: "meals",
	large: "feasts",
	huge: "banquets",
};

/** The row label `bucket` is shown under in a rendered table. */
export function labelOf(bucket: Bucket): string {
	return LABELS[bucket];
}

