// owner: OWN-9314
import { bucketTotals, formatCount, histogram, labelOf } from "./budget-table.ts";

/**
 * The bucket table for `sizes`, one string per row: a header, then one row per
 * `histogram` entry in its order, giving the bucket's label, how many Turns it
 * holds and their weighted total; see `notes/legend.md`.
 * @throws RangeError if any size is negative or not finite.
 */
export function renderTable(sizes: number[]): string[] {
	const totals = bucketTotals(sizes);
	return [
		"bucket | turns | weighted",
		...histogram(sizes).map(({ bucket, count }) =>
			[labelOf(bucket), count, formatCount(totals.get(bucket) ?? 0)].join(" | "),
		),
	];
}

